const B = "C:\\Users\\jjq21\\Desktop\\github\\My-second-brain\\";
const L: string[] = [];
L.push("/**");
L.push(" * Reddit 副业社区存档抓取（赶在 2026-11-13 RSS 关闭前）");
L.push(" *");
L.push(" * 用法：node reddit-archive.mjs [输出目录]");
L.push(" * 特点：");
L.push(" * - 每个 sub 间隔 100 秒（规避 429）");
L.push(" * - 遇 429 自动退避重试");
L.push(" * - 增量写入，中断不丢已抓内容");
L.push(" * - 输出 Markdown，按 sub 分节");
L.push(" */");
L.push("import http from 'node:http';");
L.push("import fs from 'node:fs';");
L.push("import path from 'node:path';");
L.push("");
L.push("const PROXY = { host: '127.0.0.1', port: 7897 };");
L.push("const UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/155.0.0.0 Safari/537.36';");
L.push("const OUT_DIR = process.argv[2] || 'C:/Users/jjq21/Desktop/github/My-second-brain/40-产出/情报/reddit存档';");
L.push("const OUT_FILE = path.join(OUT_DIR, 'reddit副业存档.md');");
L.push("");
L.push("// 抓取目标：副业 / 独立开发 / 变现相关");
L.push("const SUBS = [");
L.push(" 'sidehustle', 'beermoney', 'microsaas', 'juststart', 'indiehackers',");
L.push(" 'EntrepreneurRideAlong', 'Entrepreneur', 'SaaS', 'passive_income',");
L.push(" 'selfhosted', 'n8n', 'AI_Agents',");
L.push("];");
L.push("");
L.push("function get(url, accept) {");
L.push(" return new Promise((resolve, reject) => {");
L.push(" const pu = new URL(url);");
L.push(" http.get({");
L.push(" host: PROXY.host, port: PROXY.port, path: url,");
L.push(" headers: { Host: pu.host, 'User-Agent': UA, Accept: accept || 'application/rss+xml' },");
L.push(" }, (res) => {");
L.push(" const c = [];");
L.push(" res.on('data', d => c.push(d));");
L.push(" res.on('end', () => resolve({ status: res.statusCode, body: Buffer.concat(c).toString('utf8') }));");
L.push(" }).on('error', reject);");
L.push(" });");
L.push("}");
L.push("");
L.push("const sleep = ms => new Promise(r => setTimeout(r, ms));");
L.push("");
L.push("function clean(s) {");
L.push(" return String(s || '')");
L.push(" .replace(/<!\\[CDATA\\[/g, '').replace(/\\]\\]>/g, '')");
L.push(" .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&')");
L.push(" .replace(/&#39;/g, String.fromCharCode(39)).replace(/&quot;/g, String.fromCharCode(34)).replace(/&nbsp;/g, ' ')");
L.push(" .replace(/<[^>]+>/g, ' ').replace(/\\s+/g, ' ').trim();");
L.push("}");
L.push("");
L.push("async function getWithRetry(url, maxTries = 4) {");
L.push(" let wait = 60000;");
L.push(" for (let t = 1; t <= maxTries; t++) {");
L.push(" const r = await get(url);");
L.push(" if (r.status === 200 && r.body.length > 1000) return r;");
L.push(" console.log(' 尝试 ' + t + '/' + maxTries + ' 失败 (status ' + r.status + ')，等待 ' + Math.round(wait / 1000) + 's');");
L.push(" await sleep(wait);");
L.push(" wait *= 2;");
L.push(" }");
L.push(" return null;");
L.push("}");
L.push("");
L.push("function parseEntries(xml) {");
L.push(" const out = [];");
L.push(" for (const e of xml.split('<entry>').slice(1)) {");
L.push(" const t = /<title>([\\s\\S]*?)<\\/title>/.exec(e);");
L.push(" const ct = /<content type=\"html\">([\\s\\S]*?)<\\/content>/.exec(e);");
L.push(" const l = /<link href=\"([^\"]+)\"/.exec(e);");
L.push(" const u = /<updated>([^<]+)</.exec(e);");
L.push(" const a = /<name>([\\s\\S]*?)<\\/name>/.exec(e);");
L.push(" out.push({");
L.push(" title: clean(t ? t[1] : '?'),");
L.push(" body: clean(ct ? ct[1] : ''),");
L.push(" url: l ? l[1] : '',");
L.push(" date: u ? u[1].slice(0, 10) : '',");
L.push(" author: clean(a ? a[1] : ''),");
L.push(" });");
L.push(" }");
L.push(" return out;");
L.push("}");
L.push("");
L.push("// ── 主流程 ──────────────────────────────────────────────");
L.push("fs.mkdirSync(OUT_DIR, { recursive: true });");
L.push("");
L.push("const header = [");
L.push(" '# Reddit 副业社区存档',");
L.push(" '',");
L.push(" '> 抓取时间：' + new Date().toISOString().slice(0, 19).replace('T', ' ') + '（UTC）',");
L.push(" '> 来源：Reddit RSS /r/<sub>/top/.rss?t=year',");
L.push(" '> **⚠️ Reddit RSS 将于 2026-11-13 关闭，这是关闭前的存档。**',");
L.push(" '> 每个 sub 取 top/year 25 条，含标题、日期、作者、正文全文。',");
L.push(" '',");
L.push(" '---',");
L.push(" '',");
L.push("].join('\\n');");
L.push("");
L.push("let archive = header;");
L.push("fs.writeFileSync(OUT_FILE, archive, 'utf8');");
L.push("");
L.push("let total = 0;");
L.push("for (let i = 0; i < SUBS.length; i++) {");
L.push(" const sub = SUBS[i];");
L.push(" console.log('[' + (i + 1) + '/' + SUBS.length + '] r/' + sub);");
L.push(" if (i > 0) await sleep(100000);");
L.push("");
L.push(" const r = await getWithRetry('https://www.reddit.com/r/' + sub + '/top/.rss?t=year');");
L.push(" if (!r) {");
L.push(" archive += '\\n## r/' + sub + '\\n\\n（抓取失败，已跳过）\\n';");
L.push(" fs.writeFileSync(OUT_FILE, archive, 'utf8');");
L.push(" continue;");
L.push(" }");
L.push("");
L.push(" const entries = parseEntries(r.body);");
L.push(" archive += '\\n## r/' + sub + '（' + entries.length + ' 条）\\n\\n';");
L.push(" for (const e of entries) {");
L.push(" archive += '### ' + e.title + '\\n\\n';");
L.push(" archive += '- 日期：' + e.date + '\\n';");
L.push(" if (e.author) archive += '- 作者：u/' + e.author + '\\n';");
L.push(" if (e.url) archive += '- 链接：' + e.url + '\\n';");
L.push(" archive += '\\n' + e.body + '\\n\\n';");
L.push(" total++;");
L.push(" }");
L.push(" archive += '\\n---\\n';");
L.push(" fs.writeFileSync(OUT_FILE, archive, 'utf8');");
L.push(" console.log(' 已存 ' + entries.length + ' 条，累计 ' + total);");
L.push("}");
L.push("");
L.push("archive += '\\n**存档完成，共 ' + total + ' 条。**\\n';");
L.push("fs.writeFileSync(OUT_FILE, archive, 'utf8');");
L.push("console.log('DONE 共 ' + total + ' 条 -> ' + OUT_FILE);");
await tools.write({ file_path: B + "50-知识\\AI工具\\_scripts\\reddit-archive.mjs", content: L.join("\n") });
console.log("archive script written:", L.join("\n").length, "chars");
